#include <vector>

// Mock Point_2 and orientation for testing
struct Point_2 {
    double x, y;
    Point_2() : x(0), y(0) {}
    Point_2(double x, double y) : x(x), y(y) {}
};

namespace CGAL {
    enum Orientation { LEFT_TURN, RIGHT_TURN, COLLINEAR };

    Orientation orientation(const Point_2& p, const Point_2& q, const Point_2& r) {
        double val = (q.y - p.y) * (r.x - q.x) - (q.x - p.x) * (r.y - q.y);
        if (val > 0) return LEFT_TURN;
        if (val < 0) return RIGHT_TURN;
        return COLLINEAR;
    }
}

bool is_polygon_convex(const std::vector<Point_2>& polygon) {
    if (polygon.size() < 3) return false;

    CGAL::Orientation first_orient = CGAL::Orientation::COLLINEAR;
    int n = polygon.size();

    for (int i = 0; i < n; ++i) {
        const Point_2& p = polygon[i];
        const Point_2& q = polygon[(i + 1) % n];
        const Point_2& r = polygon[(i + 2) % n];

        CGAL::Orientation orient = CGAL::orientation(p, q, r);

        if (orient == CGAL::Orientation::COLLINEAR) continue;

        if (first_orient == CGAL::Orientation::COLLINEAR) {
            first_orient = orient;
        } else if (orient != first_orient) {
            return false;
        }
    }

    return first_orient != CGAL::Orientation::COLLINEAR;
}

int main() {
    // Test cases
    std::vector<Point_2> convex = {Point_2(0,0), Point_2(1,0), Point_2(1,1), Point_2(0,1)};
    std::vector<Point_2> concave = {Point_2(0,0), Point_2(2,0), Point_2(1,1), Point_2(2,2), Point_2(0,2)};
    std::vector<Point_2> collinear = {Point_2(0,0), Point_2(1,0), Point_2(2,0)};
    std::vector<Point_2> triangle = {Point_2(0,0), Point_2(1,0), Point_2(0,1)};

    // Should be true
    bool test1 = is_polygon_convex(convex);
    bool test2 = is_polygon_convex(triangle);

    // Should be false
    bool test3 = is_polygon_convex(concave);
    bool test4 = is_polygon_convex(collinear);
    bool test5 = is_polygon_convex(std::vector<Point_2>());

    return (test1 && test2 && !test3 && !test4 && !test5) ? 0 : 1;
}

